const std = @import("std");

const Color = enum { red, green, blue };
const Point = struct { x: i32, y: i32 };

test "comptime reflection" {
    const type_info = @typeInfo(Point);
    const fields = type_info.@"struct".fields;

    inline for (fields) |field| {
        _ = field;
        // field.name, field.type, field.default_value
    }

    try std.testing.expect(@hasField(Point, "x"));
    try std.testing.expect(!@hasField(Point, "z"));

    const color: Color = .green;
    try std.testing.expectEqualStrings("green", @tagName(color));

    // @field access
    const pt = Point{ .x = 10, .y = 20 };
    try std.testing.expectEqual(pt.x, @field(pt, "x"));
}

// Generic debug printer using reflection
fn printStruct(value: anytype) void {
    const T = @TypeOf(value);
    const fields = @typeInfo(T).@"struct".fields;
    inline for (fields) |field| {
        std.debug.print("{s}: {any}\n", .{ field.name, @field(value, field.name) });
    }
}

