// Arena allocator
fn arenaProcess(data: []const u8) !void {
    var arena = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena.deinit();

    const alloc = arena.allocator();
    var list = std.ArrayList(u8).init(alloc);
    defer list.deinit();
    try list.appendSlice(data);
}

