fn getCpuId(leaf: u32) u64 {
    return asm volatile ("cpuid"
        : [eax] "={eax}" (-> u32),
          [edx] "={edx}" (-> u32),
        : [leaf] "{eax}" (leaf),
        : "ebx", "ecx"
    );
}

fn breakpoint() void {
    asm volatile ("int3");
}

fn readTsc() u64 {
    return asm volatile ("rdtsc"
        : [eax] "={eax}" (-> u32),
          [edx] "={edx}" (-> u32),
    );
}

