Bitwise & Shift Operators:
const std = @import("std");

test "bitwise" {
    const a: u8 = 0b1100_1100;
    const b: u8 = 0b1010_1010;

    try std.testing.expectEqual(@as(u8, 0b1000_1000), a & b);
    try std.testing.expectEqual(@as(u8, 0b1110_1110), a | b);
    try std.testing.expectEqual(@as(u8, 0b0110_0110), a ^ b);
    try std.testing.expectEqual(@as(u8, 0b0011_0011), ~a);

    // Shifts
    const c: u8 = 0b0000_0001;
    try std.testing.expectEqual(@as(u8, 0b0000_0100), c << 2);

    // Arithmetic vs logical right shift
    const neg: i8 = -8;           // 1111_1000
    try std.testing.expectEqual(@as(i8, -2), neg >> 2);  // arithmetic: 1111_1110

    // Compile-time bit manipulation
    const flags = comptime flags: {
        var f: u32 = 0;
        f |= 1 << 0;  // bit 0
        f |= 1 << 2;  // bit 2
        break :flags f;
    };
}

