Operator Overloading & Custom Types:
const std = @import("std");

const Complex = struct {
    real: f64,
    imag: f64,

    pub fn add(self: Complex, other: Complex) Complex {
        return Complex{
            .real = self.real + other.real,
            .imag = self.imag + other.imag,
        };
    }

    pub fn mul(self: Complex, other: Complex) Complex {
        return Complex{
            .real = self.real * other.real - self.imag * other.imag,
            .imag = self.real * other.imag + self.imag * other.real,
        };
    }

    pub fn format(self: Complex, comptime fmt: []const u8, options: std.fmt.FormatOptions, writer: anytype) !void {
        _ = fmt;
        _ = options;
        try writer.print("{} + {}i", .{ self.real, self.imag });
    }
};

test "complex without operator overloading" {
    const a = Complex{ .real = 1.0, .imag = 2.0 };
    const b = Complex{ .real = 3.0, .imag = 4.0 };
    const sum = a.add(b);
    try std.testing.expectEqual(@as(f64, 4.0), sum.real);
    try std.testing.expectEqual(@as(f64, 6.0), sum.imag);
}
